import { delay, omitEmpty } from '@splendidlabz/utils'
import {
  Focusable,
  addListeners,
  isTab,
  manageFocus,
  removeListeners,
  trapFocus,
} from '@splendidlabz/utils/dom'

// ========================================
// Default Options
// ========================================
/**
 * @typedef {Object} DisclosureTriggerOpts
 * @property {boolean} showOnHover - Show disclosure content on hover.
 * @property {boolean} showOnFocus - Show disclosure content on focus.
 * @property {number} hoverCloseDelay - Delay in milliseconds before closing disclosure content on mouse leave.
 * @property {boolean} closeOthers - Close other disclosures when opening this disclosure.
 */
export const DEFAULT_DISCLOSURE_TRIGGER_OPTS = {
  showOnClick: true,
  showOnHover: false,
  showOnFocus: false,
  hoverCloseDelay: 120,
  closeOthers: true,
}

export const DISCLOSURE_TRIGGER_OPT_KEYS = Object.keys(
  DEFAULT_DISCLOSURE_TRIGGER_OPTS,
)

/**
 * @typedef {Object} DisclosureContentOpts
 * @property {boolean} trapFocus - Trap focus within disclosure content.
 * @property {(string|HTMLElement)} focusTargetWhenOpening - Focus target when disclosure content is opened. Can be 'first', 'content', or an HTMLElement.
 */
export const DEFAULT_DISCLOSURE_CONTENT_OPTS = {
  lightDismiss: true,
  focusManagement: 'manage', // false, `manage`, `trap`
  focusTargetWhenOpen: 'content', // || false, 'first', 'content'. HTMLElement.
  focusTargetWhenClose: 'trigger', // false
  useTriggerWidth: false,
}

export const DISCLOSURE_CONTENT_OPT_KEYS = Object.keys(
  DEFAULT_DISCLOSURE_CONTENT_OPTS,
)

// ========================================
// Shared state
// ========================================
const disclosures = $state([])

export function getDisclosure(id) {
  return disclosures.find(d => d.id === id)
}

export function initDisclosure(part, disclosureInfo) {
  const { id } = disclosureInfo
  const d = getDisclosure(id)
  if (!d) {
    disclosures.push(disclosureInfo)
    return getDisclosure(id)
  }

  // If trigger or content is already initialized, don't re-init
  if (part === 'trigger' && d.nodes.trigger) return d
  if (part === 'content' && d.nodes.content) return d

  // Initialize new info from trigger or content
  d.state = { ...d.state, ...omitEmpty(disclosureInfo.state) }
  d.options = { ...d.options, ...omitEmpty(disclosureInfo.options) }
  d.nodes = {
    ...d.nodes,
    ...omitEmpty(disclosureInfo.nodes, { shallow: true }),
  }

  return d
}

// ========================================
// Actions
// ========================================
/**
 * Disclosure Trigger
 * @prop {HTMLElement} node - The trigger element.
 * @prop {DisclosureTriggerOpts} props - The trigger options.
 */
export function disclosureTrigger(node, props = {}) {
  const id = node.getAttribute('target')
  const disclosureInfo = {
    id,
    state: { show: false, ...omitEmpty(props.state) },
    nodes: { trigger: node },
    options: {
      ...DEFAULT_DISCLOSURE_TRIGGER_OPTS,
      ...props.options,
    },
  }

  const d = initDisclosure('trigger', disclosureInfo)
  node.setAttribute('aria-expanded', d.state.show)

  const listeners = [
    {
      event: 'click',
      node,
      handler: handleClick,
    },
    {
      event: 'keydown',
      node,
      handler: closeOnEscapeButton,
    },
    {
      event: 'keydown',
      node,
      handler: tabOntoContent,
    },
    {
      event: 'pointerenter',
      node,
      handler: handlePointerEnter,
    },
    {
      event: 'pointerleave',
      node,
      handler: handlePointerLeave,
    },
    {
      event: 'focusin',
      node,
      handler: handleFocusIn,
    },
    {
      event: 'focusout',
      node,
      handler: handleFocusOut,
    },
  ]

  function handleClick(event) {
    if (d.options.showOnClick) {
      if (d.state.show === false) return open(d)
      if (d.state.show === true) return close(d)
    }
  }

  function closeOnEscapeButton(event) {
    if (event.key !== 'Escape') return
    if (d.options.lightDismiss) close(d)
  }

  function tabOntoContent(event) {
    if (d.state.show === false) return
    if (isTab(event)) {
      event.preventDefault()
      d.nodes.contentFocusables.first?.focus()
    }
  }

  // function backToDisclosureContent(event) {
  // if (d.options.shiftTabBackToContent === false) return
  // if (isShiftTab(event) && d.state.show === true) {
  //   setTimeout(_ => {
  //     d.nodes.content.focus({ preventScroll: true })
  //   }, 0)
  // }
  // }

  function handlePointerEnter(event) {
    if (d.options.showOnHover) {
      d.state.pointerLocation = 'trigger'
      open(d)
    }
  }

  async function handlePointerLeave(event) {
    if (d.options.showOnHover) {
      d.state.pointerLocation = null

      await delay(d.options.hoverCloseDelay)
      if (d.state.pointerLocation === null) {
        d.state.isMouseOut = true
        close(d)
        d.state.isMouseOut = false
      }
    }
  }

  function handleFocusIn(event) {
    if (d.options.showOnFocus) open(d)
  }

  function handleFocusOut() {
    if (d.options.showOnFocus) close(d)
  }

  addListeners(listeners)

  return {
    destroy() {
      removeListeners(listeners)
    },
  }
}

/**
 * Disclosure Content action.
 * Disclosure content will only activate when d.state.show is updated to true
 * @prop {HTMLElement} node - The trigger element.
 * @prop {DisclosureContentOpts} props - The trigger options.
 */
export function disclosureContent(node, props = {}) {
  const id = node.getAttribute('id')
  const contentFocusables = Focusable(node)

  const disclosureInfo = {
    id,
    state: omitEmpty(props.state),
    nodes: { content: node, contentFocusables },
    options: {
      ...DEFAULT_DISCLOSURE_CONTENT_OPTS,
      ...omitEmpty(props.options),
    },
  }

  // Initialize the disclosure
  const d = initDisclosure('content', disclosureInfo)
  contentOpeningActions(d)

  // Add event listeners
  const listeners = [
    {
      event: 'click',
      node: document,
      handler: handleOutsideClick,
    },

    {
      event: 'keydown',
      node,
      handler: handleKeydown,
    },
    {
      event: 'mouseenter',
      node,
      handler: handleMouseEnter,
    },
    {
      event: 'mouseleave',
      node,
      handler: handleMouseLeave,
    },
  ]

  addListeners(listeners)

  return {
    destroy() {
      removeListeners(listeners)
    },
  }

  // ========================
  // Event Listeners
  // ========================
  // Close if click is outside of contentNode and triggerNode
  function handleOutsideClick(event) {
    const { lightDismiss } = d.options
    if (lightDismiss === false) return
    if (d.nodes.content.contains(event.target)) return
    if (d.nodes.trigger.contains(event.target)) return
    // Only close if state is currently set to show
    if (d.state.show) {
      if (d.options.closeOthers) close(d)
      else if (!clickedOnOtherDisclosureNodes(event.target, d.id)) close(d)
    }
  }

  function handleKeydown(event) {
    const { focusManagement } = d.options

    if (focusManagement === 'trap') {
      trapFocus({ event, focusables: d.nodes.contentFocusables })
    }

    if (focusManagement === 'manage') {
      manageFocus({
        event,
        triggerNode: d.nodes.trigger,
        contentNode: d.nodes.content,
        focusables: d.nodes.contentFocusables,
        shouldFocusTriggerWhenTabbingOut: d.options.focusTriggerWhenTabbingOut,
        onLeave(direction) {
          if (direction === 'forward') close(d)
        },
      })
    }

    if (d.options.lightDismiss) closeOnEscape(event)
  }

  function closeOnEscape(event) {
    if (event.key === 'Escape') close(d, { shouldFocusTrigger: true })
  }

  function handleMouseEnter() {
    if (!d.options.showOnHover) return
    d.state.pointerLocation = 'content'
  }

  function handleMouseLeave() {
    if (!d.options.showOnHover) return
    d.state.pointerLocation = null
    close(d)
  }
}

// ========================================
// Methods
// ========================================
export function open(d) {
  if (d.state.show) return
  const { trigger } = d.nodes
  const { onbeforeopen, onbeforetoggle } = d.options

  runEventCallback(onbeforeopen, d, { event: 'beforeopen' })
  runEventCallback(onbeforetoggle, d, { event: 'beforetoggle' })

  d.state.show = true

  trigger.setAttribute('aria-expanded', d.state.show)
  if (d.options.closeOthers) closeOthersExcept(d.id)

  // Note: The rest of the opening actions are handled openingActions after we retrieve disclosureContent props
}

function contentOpeningActions(d) {
  const { content: node, contentFocusables } = d.nodes
  const { focusTargetWhenOpen, useTriggerWidth, onopen, ontoggle } = d.options
  node.setAttribute('tabindex', '-1')

  if (useTriggerWidth) {
    const { width: triggerWidth } = d.nodes.trigger.getBoundingClientRect()
    node.style.width = triggerWidth + 'px'
  }

  // Set focus.
  // This requires timeout. Otherwise focus is set too early.
  setTimeout(_ => {
    const hasAutofocus = node.querySelector('autofocus')

    if (focusTargetWhenOpen && !hasAutofocus) {
      if (focusTargetWhenOpen instanceof HTMLElement) {
        focusTargetWhenOpen.focus()
      }
      if (focusTargetWhenOpen === 'content') {
        node.setAttribute('tabindex', '-1')
        node.focus()
      }
      if (focusTargetWhenOpen === 'first') contentFocusables.first?.focus()
      if (focusTargetWhenOpen === 'second') contentFocusables[1]?.focus()
    }

    runEventCallback(onopen, d, { event: 'open' })
    runEventCallback(ontoggle, d, { event: 'toggle' })
  }, 1)
}

export function close(d, { shouldFocusWhenClosing = true } = {}) {
  if (!d.state.show) return

  const { trigger } = d.nodes
  const { isMouseOut } = d.state
  const {
    focusTargetWhenClose,
    onbeforeclose,
    onbeforetoggle,
    onclose,
    ontoggle,
  } = d.options

  d.state.show = false

  runEventCallback(onbeforeclose, d, { event: 'beforeclose' })
  runEventCallback(onbeforetoggle, d, { event: 'beforetoggle' })

  trigger.setAttribute('aria-expanded', d.state.show)

  // Decide whether to focus on trigger
  if (focusTargetWhenClose === false) shouldFocusWhenClosing = false
  // Mouseout can cause focus to jump around
  if (isMouseOut) shouldFocusWhenClosing = false

  // Focuses on trigger
  if (shouldFocusWhenClosing) trigger.focus()

  // Run close events
  runEventCallback(onclose, d, { event: 'close' })
  runEventCallback(ontoggle, d, { event: 'toggle' })
}

function closeOthersExcept(id) {
  disclosures.forEach(d => {
    if (d.id !== id) close(d, { shouldFocusWhenClosing: false })
  })
}

function clickedOnOtherDisclosureNodes(target, id) {
  const disclosures = getDisclosures()
  return disclosures.some(d => {
    if (d.id === id) return false
    if (d.nodes.trigger?.contains(target)) return true
    if (d.nodes.content?.contains(target)) return true
    return false
  })
}

function getEventProps(event, d) {
  let oldState = !d.state.show
  let newState = d.state.show

  if (event.includes('before')) {
    ;[oldState, newState] = [newState, oldState]
  }

  return {
    oldState: toPopoverState(oldState),
    newState: toPopoverState(newState),
  }
}

function toPopoverState(state) {
  return state ? 'open' : 'closed'
}

function runEventCallback(fn, data, { event }) {
  if (typeof fn === 'function') {
    fn(getEventProps(event || fn.name, data))
  }
}
